Script:
# Deploy IIS website
#
# Creates or updates an IIS application pool and website on the target machine.
# The website content is expected to already be on disk - chain this step after a
# "Deploy package" step that installs files into the physical path.
#
# This template runs under Windows PowerShell (powershell5) because WebAdministration
# is a Windows-only module that is not loadable in PowerShell 7 without a compatibility session.

function Get-JawsText ($name, $default = "") {
  $param = $Jaws.Parameters[$name]
  if ($null -eq $param) { return $default }

  $value = $param.Value
  if ($null -eq $value) { return $default }
  if (($value -is [string]) -and [string]::IsNullOrWhiteSpace($value)) { return $default }

  return "$value".Trim()
}

function Get-JawsBool ($name, $default = $false) {
  $param = $Jaws.Parameters[$name]
  if ($null -eq $param) { return $default }

  $value = $param.Value
  if ($null -eq $value) { return $default }
  if ($value -is [bool]) { return $value }

  # A checkbox bound to a variable arrives as text - coerce it here.
  $text = "$value".Trim()
  if ([string]::IsNullOrWhiteSpace($text)) { return $default }

  return @("true", "1", "yes", "on") -contains $text.ToLowerInvariant()
}

function Get-JawsInt ($name, $default) {
  $text = Get-JawsText $name ""
  if ([string]::IsNullOrWhiteSpace($text)) { return $default }

  $parsed = 0
  if (-not [int]::TryParse($text, [ref]$parsed)) { return $default }
  if ($parsed -le 0) { return $default }

  return $parsed
}

function Invoke-IisWithRetry ($description, [scriptblock]$action) {
  for ($attempt = 1; $attempt -le $script:maxRetries; $attempt++) {
    try {
      return & $action
    }
    catch {
      if ($attempt -ge $script:maxRetries) {
        throw "Failed to $description after $script:maxRetries attempt(s): $($_.Exception.Message)"
      }

      $delay = Get-Random -Minimum 1 -Maximum 5
      Write-Host "Attempt $attempt to $description failed ($($_.Exception.Message)) - retrying in $delay second(s)"
      Start-Sleep -Seconds $delay
    }
  }
}

# Parses a single binding line: "protocol ip:port:hostname [certificate-thumbprint] [sni]"
function ConvertTo-IisBinding ($line) {
  $parts = @($line -split '\s+' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
  if ($parts.Count -lt 2) {
    throw "Binding '$line' is invalid. Expected format: protocol ip:port:hostname [certificate-thumbprint] [sni]"
  }

  $protocol = $parts[0].TrimEnd(':', '/').ToLowerInvariant()
  if (@("http", "https") -notcontains $protocol) {
    throw "Binding '$line' uses unsupported protocol '$protocol'. Only http and https are supported."
  }

  $addressParts = $parts[1] -split ':'
  if ($addressParts.Count -lt 2) {
    throw "Binding '$line' is invalid. The address must be in the format ip:port:hostname, e.g. *:80:"
  }

  $ipAddress = $addressParts[0].Trim()
  if ([string]::IsNullOrWhiteSpace($ipAddress)) { $ipAddress = "*" }

  $port = 0
  if (-not [int]::TryParse($addressParts[1].Trim(), [ref]$port)) {
    throw "Binding '$line' has a non-numeric port '$($addressParts[1])'"
  }

  $hostHeader = ""
  if ($addressParts.Count -ge 3) { $hostHeader = $addressParts[2].Trim() }

  $thumbprint = ""
  $sni = $false
  for ($i = 2; $i -lt $parts.Count; $i++) {
    if ($parts[$i].ToLowerInvariant() -eq "sni") {
      $sni = $true
    }
    else {
      # Tolerate thumbprints copied from certmgr, which contain spaces and invisible characters.
      $thumbprint += ($parts[$i] -replace '[^0-9a-fA-F]', '')
    }
  }

  if ($protocol -eq "https" -and [string]::IsNullOrWhiteSpace($thumbprint)) {
    throw "Binding '$line' is https but has no certificate thumbprint. Add the thumbprint of a certificate installed in the LocalMachine\My store of this machine."
  }

  if ($protocol -eq "http" -and -not [string]::IsNullOrWhiteSpace($thumbprint)) {
    throw "Binding '$line' is http but specifies a certificate thumbprint. Use https for certificate bindings."
  }

  if ($sni -and [string]::IsNullOrWhiteSpace($hostHeader)) {
    throw "Binding '$line' enables sni but has no hostname. Server Name Indication requires a hostname."
  }

  return [pscustomobject]@{
    Protocol           = $protocol
    IPAddress          = $ipAddress
    Port               = $port
    HostHeader         = $hostHeader
    Thumbprint         = $thumbprint.ToUpperInvariant()
    Sni                = $sni
    BindingInformation = "$($ipAddress):$($port):$hostHeader"
  }
}

function Assert-IisAvailable {
  # IIS configuration is only readable from an elevated process. Checking up front turns an
  # obscure "Process should have elevated status" failure into an actionable message.
  $identity = [System.Security.Principal.WindowsIdentity]::GetCurrent()
  $isElevated = (New-Object System.Security.Principal.WindowsPrincipal($identity)).IsInRole(
    [System.Security.Principal.WindowsBuiltInRole]::Administrator)

  if (-not $isElevated) {
    throw "IIS configuration cannot be read or modified because this deployment is not running elevated (current account: $($identity.Name)). Run the Jaws agent on this machine as a service under an account with local administrator rights."
  }

  try {
    Import-Module WebAdministration -ErrorAction Stop
  }
  catch {
    throw "IIS is not available on this machine - the WebAdministration PowerShell module could not be loaded ($($_.Exception.Message)). Install the IIS management tools before running this step, e.g. 'Install-WindowsFeature Web-Server, Web-Mgmt-Console, Web-Scripting-Tools' on Windows Server, or 'Enable-WindowsOptionalFeature -Online -FeatureName IIS-WebServerRole, IIS-ManagementScriptingTools' on Windows client."
  }

  if (-not (Test-Path "IIS:\")) {
    throw "IIS is not available on this machine - the IIS: drive could not be found even though WebAdministration loaded. Check that the World Wide Web Publishing Service (W3SVC) is installed."
  }

  Write-Host "IIS is available - WebAdministration module loaded"
}

function Set-IisApplicationPool ($poolName, $frameworkVersion, $pipelineMode, $enable32Bit, $identityType, $username, $password) {
  $poolPath = "IIS:\AppPools\$poolName"

  if (-not (Test-Path $poolPath)) {
    Write-Host "Creating application pool: $poolName"
    Invoke-IisWithRetry "create application pool '$poolName'" { New-Item $poolPath -Type AppPool | Out-Null }
  }
  else {
    Write-Host "Application pool already exists - updating: $poolName"
  }

  # "No managed code" is expressed as an empty managedRuntimeVersion in IIS.
  $runtimeVersion = if ($frameworkVersion -eq "NoManagedCode") { "" } else { $frameworkVersion }
  # managedPipelineMode is an enum: 0 = Integrated, 1 = Classic.
  $pipelineValue = if ($pipelineMode -eq "Classic") { 1 } else { 0 }

  Invoke-IisWithRetry "set application pool properties on '$poolName'" {
    Set-ItemProperty $poolPath -Name "managedRuntimeVersion" -Value $runtimeVersion
    Set-ItemProperty $poolPath -Name "managedPipelineMode" -Value $pipelineValue
    Set-ItemProperty $poolPath -Name "enable32BitAppOnWin64" -Value $enable32Bit
    Set-ItemProperty $poolPath -Name "autoStart" -Value $true
  }

  Write-Host "Application pool runtime: $(if ($runtimeVersion) { $runtimeVersion } else { 'No managed code' }), pipeline: $(if ($pipelineValue -eq 1) { 'Classic' } else { 'Integrated' }), 32-bit: $enable32Bit"

  if ($identityType -eq "SpecificUser") {
    if ([string]::IsNullOrWhiteSpace($username)) {
      throw "Application pool identity is set to 'User account' but no user account name was provided."
    }

    Write-Host "Setting application pool identity to user account: $username"
    Invoke-IisWithRetry "set application pool identity on '$poolName'" {
      Set-ItemProperty $poolPath -Name "processModel" -Value @{ identitytype = "SpecificUser"; username = $username; password = $password }
    }
  }
  else {
    Write-Host "Setting application pool identity to: $identityType"
    Invoke-IisWithRetry "set application pool identity on '$poolName'" {
      Set-ItemProperty $poolPath -Name "processModel" -Value @{ identitytype = $identityType }
    }
  }
}

function Set-IisWebSite ($siteName, $physicalPath, $poolName, $bindings) {
  $sitePath = "IIS:\Sites\$siteName"

  if (-not (Test-Path $sitePath)) {
    # A site cannot be created without at least one binding, so the first one is applied up front.
    $firstBinding = $bindings[0]
    Write-Host "Creating website '$siteName' with initial binding $($firstBinding.Protocol) $($firstBinding.BindingInformation)"

    Invoke-IisWithRetry "create website '$siteName'" {
      New-Item $sitePath -Type Site -Bindings @{ protocol = $firstBinding.Protocol; bindingInformation = $firstBinding.BindingInformation } | Out-Null
    }
  }
  else {
    Write-Host "Website already exists - updating: $siteName"
  }

  Invoke-IisWithRetry "set website properties on '$siteName'" {
    Set-ItemProperty $sitePath -Name "physicalPath" -Value $physicalPath
    Set-ItemProperty $sitePath -Name "applicationPool" -Value $poolName
  }

  Write-Host "Website physical path: $physicalPath, application pool: $poolName"
}

function Set-IisBindings ($siteName, $bindings, $removeOtherBindings) {
  foreach ($binding in $bindings) {
    $existing = @(Get-WebBinding -Name $siteName |
        Where-Object { $_.protocol -eq $binding.Protocol -and $_.bindingInformation -eq $binding.BindingInformation })

    if ($existing.Count -eq 0) {
      Write-Host "Adding binding: $($binding.Protocol) $($binding.BindingInformation)$(if ($binding.Sni) { ' (sni)' })"

      Invoke-IisWithRetry "add binding '$($binding.Protocol) $($binding.BindingInformation)'" {
        if ($binding.Sni) {
          New-WebBinding -Name $siteName -Protocol $binding.Protocol -IPAddress $binding.IPAddress -Port $binding.Port -HostHeader $binding.HostHeader -SslFlags 1
        }
        else {
          New-WebBinding -Name $siteName -Protocol $binding.Protocol -IPAddress $binding.IPAddress -Port $binding.Port -HostHeader $binding.HostHeader
        }
      }
    }
    else {
      Write-Host "Binding already present: $($binding.Protocol) $($binding.BindingInformation)"
    }

    if ($binding.Protocol -eq "https") {
      # Always re-apply the certificate so a rotated thumbprint takes effect on redeployment.
      Write-Host "Binding certificate $($binding.Thumbprint) to $($binding.BindingInformation)"

      Invoke-IisWithRetry "bind certificate to '$($binding.BindingInformation)'" {
        $certificate = Get-Item "Cert:\LocalMachine\My\$($binding.Thumbprint)" -ErrorAction SilentlyContinue
        if ($null -eq $certificate) {
          throw "Certificate with thumbprint $($binding.Thumbprint) was not found in the LocalMachine\My store of this machine"
        }

        $webBinding = Get-WebBinding -Name $siteName -Protocol "https" |
          Where-Object { $_.bindingInformation -eq $binding.BindingInformation }

        $webBinding.AddSslCertificate($binding.Thumbprint, "My")
      }
    }
  }

  if (-not $removeOtherBindings) {
    return
  }

  $desired = @($bindings | ForEach-Object { "$($_.Protocol)|$($_.BindingInformation)" })

  foreach ($existing in @(Get-WebBinding -Name $siteName)) {
    $key = "$($existing.protocol)|$($existing.bindingInformation)"
    if ($desired -contains $key) {
      continue
    }

    Write-Host "Removing binding that is not listed in the step: $($existing.protocol) $($existing.bindingInformation)"
    $parts = $existing.bindingInformation -split ':'

    Invoke-IisWithRetry "remove binding '$($existing.bindingInformation)'" {
      Remove-WebBinding -Name $siteName -Protocol $existing.protocol -IPAddress $parts[0] -Port $parts[1] -HostHeader $parts[2]
    }
  }
}

function Set-IisAuthentication ($siteName, $authenticationName, $setting) {
  if ($setting -eq "Unchanged") {
    Write-Host "Leaving $authenticationName unchanged"
    return
  }

  $enabled = ($setting -eq "Enabled")
  Write-Host "Setting $authenticationName to: $setting"

  try {
    Invoke-IisWithRetry "set $authenticationName on '$siteName'" {
      Set-WebConfigurationProperty `
        -Filter "/system.webServer/security/authentication/$authenticationName" `
        -Name "enabled" `
        -Value $enabled `
        -PSPath "IIS:\" `
        -Location $siteName
    }
  }
  catch {
    throw "Could not set $authenticationName on website '$siteName': $($_.Exception.Message). This usually means the matching IIS role feature is not installed, or the configuration section is locked at server level. Install the feature (e.g. 'Install-WindowsFeature Web-Windows-Auth') and make sure the section is unlocked."
  }
}

function Set-IisState ($siteName, $poolName, $state) {
  if ($state -eq "Unchanged") {
    Write-Host "Leaving application pool and website state unchanged"
    return
  }

  if ($state -eq "Started") {
    Invoke-IisWithRetry "start application pool '$poolName'" {
      if ((Get-WebAppPoolState -Name $poolName).Value -ne "Started") {
        Start-WebAppPool -Name $poolName
      }
    }
    Write-Host "Application pool started: $poolName"

    Invoke-IisWithRetry "start website '$siteName'" {
      if ((Get-WebsiteState -Name $siteName).Value -ne "Started") {
        Start-Website -Name $siteName
      }
    }
    Write-Host "Website started: $siteName"
  }
  else {
    Invoke-IisWithRetry "stop website '$siteName'" {
      if ((Get-WebsiteState -Name $siteName).Value -ne "Stopped") {
        Stop-Website -Name $siteName
      }
    }
    Write-Host "Website stopped: $siteName"

    Invoke-IisWithRetry "stop application pool '$poolName'" {
      if ((Get-WebAppPoolState -Name $poolName).Value -ne "Stopped") {
        Stop-WebAppPool -Name $poolName
      }
    }
    Write-Host "Application pool stopped: $poolName"
  }
}

# --- step parameters ---

$siteName = Get-JawsText "STEP.Website.WebSiteName"
$physicalPath = Get-JawsText "STEP.Website.PhysicalPath"
$bindingLines = Get-JawsText "STEP.Website.Bindings"
$removeOtherBindings = Get-JawsBool "STEP.Website.RemoveOtherBindings"

$poolName = Get-JawsText "STEP.ApplicationPool.ApplicationPoolName"
$frameworkVersion = Get-JawsText "STEP.ApplicationPool.FrameworkVersion" "v4.0"
$pipelineMode = Get-JawsText "STEP.ApplicationPool.PipelineMode" "Integrated"
$enable32Bit = Get-JawsBool "STEP.ApplicationPool.Enable32BitAppOnWin64"
$identityType = Get-JawsText "STEP.ApplicationPool.IdentityType" "ApplicationPoolIdentity"
$username = Get-JawsText "STEP.ApplicationPool.UserAccountName"
$password = Get-JawsText "STEP.ApplicationPool.UserAccountPassword"

$anonymousAuthentication = Get-JawsText "STEP.Authentication.AnonymousAuthentication" "Unchanged"
$windowsAuthentication = Get-JawsText "STEP.Authentication.WindowsAuthentication" "Unchanged"
$basicAuthentication = Get-JawsText "STEP.Authentication.BasicAuthentication" "Unchanged"

$stateAfterDeployment = Get-JawsText "STEP.Options.StateAfterDeployment" "Started"
$script:maxRetries = Get-JawsInt "STEP.Options.MaxRetries" 5

# --- validation ---

if ([string]::IsNullOrWhiteSpace($siteName)) {
  throw "This deployment step is missing value for 'STEP.Website.WebSiteName'"
}

if ([string]::IsNullOrWhiteSpace($physicalPath)) {
  throw "This deployment step is missing value for 'STEP.Website.PhysicalPath'"
}

if ([string]::IsNullOrWhiteSpace($poolName)) {
  throw "This deployment step is missing value for 'STEP.ApplicationPool.ApplicationPoolName'"
}

$bindings = @()
foreach ($line in @($bindingLines -split "`n")) {
  if (-not [string]::IsNullOrWhiteSpace($line)) {
    $bindings += ConvertTo-IisBinding $line.Trim()
  }
}

if ($bindings.Count -eq 0) {
  throw "This deployment step is missing value for 'STEP.Website.Bindings' - at least one binding is required, e.g. 'http *:80:'"
}

# --- deployment ---

Write-Host "Deploying IIS website '$siteName' from $physicalPath"

Assert-IisAvailable

if (-not (Test-Path $physicalPath)) {
  Write-Host "Physical path is missing - creating $physicalPath"
  New-Item $physicalPath -ItemType Directory | Out-Null
}

# IIS serialises poorly under concurrent deployments: two agents writing applicationHost.config
# at the same time corrupt each other. A machine-wide mutex keeps IIS changes one at a time.
$mutex = New-Object System.Threading.Mutex($false, "Global\JawsDeploy-IIS-Configuration-Mutex")
$mutexAcquired = $false

try {
  try {
    $mutexAcquired = $mutex.WaitOne([TimeSpan]::FromMinutes(5))
  }
  catch [System.Threading.AbandonedMutexException] {
    # The previous holder died without releasing. We now own the mutex and IIS is ours to configure.
    Write-Host "Previous IIS configuration lock was abandoned - continuing"
    $mutexAcquired = $true
  }

  if (-not $mutexAcquired) {
    throw "Timed out after 5 minutes waiting for another deployment to finish configuring IIS on this machine"
  }

  Set-IisApplicationPool $poolName $frameworkVersion $pipelineMode $enable32Bit $identityType $username $password
  Set-IisWebSite $siteName $physicalPath $poolName $bindings
  Set-IisBindings $siteName $bindings $removeOtherBindings

  Set-IisAuthentication $siteName "anonymousAuthentication" $anonymousAuthentication
  Set-IisAuthentication $siteName "windowsAuthentication" $windowsAuthentication
  Set-IisAuthentication $siteName "basicAuthentication" $basicAuthentication

  Set-IisState $siteName $poolName $stateAfterDeployment
}
finally {
  if ($mutexAcquired) {
    $mutex.ReleaseMutex()
  }
  $mutex.Dispose()
}

Write-Host "IIS website deployed: $siteName"
